UPDATE groups_info
group_name = #{groupName}, group_description = #{groupDescription}, parent_group_id = #{parentGroupId}, path = #{path}, level = #{level}, sort_order = #{sortOrder}, status = #{status},
WHERE group_id = #{groupId};

mapper.select:
SELECT FROM groups_info WHERE group_id IN
#{groupId}
ORDER BY level ASC, sort_order ASC, id ASC

SELECT  FROM groups_info
WHERE parent_group_id = #{parentGroupId}
ORDER BY sort_order, id

SELECT g.*
FROM groups_info g
         JOIN (
    SELECT path FROM groups_info WHERE group_id = #{rootGroupId}
) r ON g.path LIKE CONCAT(r.path, '%')
ORDER BY g.path, g.sort_order, g.id
